const deltaStyle=document.createElement('style');
deltaStyle.textContent=`
  .r1-workspace{grid-column:1/-1;min-width:0}.r1-workspace .page-heading{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px}.r1-workspace .collection-identity{min-width:0}.r1-workspace .collection-kicker{display:block;color:var(--muted);font:10px Arial,sans-serif;letter-spacing:1.6px;margin-bottom:8px}.r1-workspace h1{margin:0;font-size:30px!important}.r1-workspace .heading-actions,.r1-workspace .toolbar,.r1-workspace .actions,.r1-workspace .detail-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.r1-workspace .r1-context,.r1-workspace .path-strip,.r1-workspace .r1-feedback{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:11px 0;border-block:1px solid var(--line);color:var(--muted);font-size:11px}.r1-workspace .r1-context>span:first-child,.r1-workspace .r1-install-footer>span{color:var(--accent);font:10px Arial,sans-serif;letter-spacing:1.4px}.r1-workspace .mods-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:26px;margin-top:18px}.r1-workspace .mods-sidebar{min-width:0;border-right:1px solid var(--line);padding-right:20px}.r1-workspace .side-section h3,.r1-workspace .r1-import-guide h3{margin:10px 0;color:var(--muted);font-size:10px!important;text-transform:uppercase}.r1-workspace .scope-choice{display:grid;gap:4px}.r1-workspace .scope-choice button{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0;padding:9px 10px;border:1px solid transparent;border-radius:var(--tfx-radius-control)!important;text-align:left;color:var(--muted);font-size:11px!important}.r1-workspace .scope-choice button.active{border-color:var(--line);background:var(--surface);color:var(--text)}.r1-workspace .scope-choice button span{color:var(--faint)}.r1-workspace .side-separator{height:1px;border:0;background:var(--line);margin:17px 0}.r1-workspace .collection-work{min-width:0}.r1-workspace .search{flex:1;min-width:190px}.r1-workspace .count-label{color:var(--muted);font-size:11px}.r1-workspace .path-strip{margin:12px 0}.r1-workspace .path-strip p{margin:5px 0 0;overflow-wrap:anywhere}.r1-workspace .path-label{font-size:10px;color:var(--faint)}.r1-workspace .mod-list{display:grid}.r1-workspace .mod-row{display:grid;grid-template-columns:28px 30px minmax(0,1fr) auto;gap:12px;align-items:center;min-width:0;padding:15px 0;border-bottom:1px solid var(--line)}.r1-workspace .mod-index{color:var(--faint);font:10px Arial,sans-serif}.r1-workspace .mod-glyph{width:28px;height:28px;display:grid;place-items:center;color:var(--accent);border:1px solid var(--line);border-radius:var(--tfx-radius-control)}.r1-workspace .mod-glyph .icon{width:15px;height:15px}.r1-workspace .mod-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.r1-workspace .mod-title strong{font-size:13px}.r1-workspace .mod-row p{margin:4px 0;color:var(--muted);font-size:11px;line-height:1.5}.r1-workspace .mod-meta{margin-top:5px;color:var(--faint);font-size:10px;overflow-wrap:anywhere}.r1-workspace .mod-state{color:var(--muted);font-size:10px}.r1-workspace .mod-row .toggle{flex:none}.r1-workspace .r1-warning{display:block;margin-top:5px;color:var(--warning)}.r1-workspace .r1-feedback{justify-content:flex-start;line-height:1.6}.r1-workspace .r1-install-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;margin-top:18px}.r1-workspace .panel{min-width:0;padding:20px;border:1px solid var(--line);border-radius:var(--tfx-radius-control)!important;background:color-mix(in srgb,var(--surface) 55%,transparent)}.r1-workspace .panel-header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-bottom:14px;border-bottom:1px solid var(--line)}.r1-workspace .panel-header h2{font-size:14px!important}.r1-workspace .section-index{margin-right:8px;color:var(--accent);font:10px Arial,sans-serif}.r1-workspace .dropzone{min-height:190px;margin-top:18px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;border:1px dashed color-mix(in srgb,var(--accent) 55%,var(--line));border-radius:var(--tfx-radius-well)!important;text-align:center;transition:background-color 160ms,border-color 160ms}.r1-workspace .dropzone.dragover{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 9%,transparent)}.r1-workspace .dropzone strong{font-size:15px}.r1-workspace .dropzone small,.r1-workspace .r1-import-guide p{color:var(--muted);font-size:11px;line-height:1.65}.r1-workspace .r1-import-guide{margin-top:18px}.r1-workspace .r1-import-guide p{margin:5px 0}.r1-workspace .r1-preview-list{max-height:190px;overflow:auto}.r1-workspace .r1-preview-row{display:grid;grid-template-columns:54px minmax(0,1fr);gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.r1-workspace .r1-preview-row>span{color:var(--accent);font:10px Arial,sans-serif}.r1-workspace .r1-preview-row strong{font-size:12px}.r1-workspace .r1-preview-row p,.r1-workspace .r1-preview-row small{display:block;margin:5px 0;color:var(--muted);font-size:10px;overflow-wrap:anywhere}.r1-workspace .r1-format-label{color:var(--accent);font:10px Arial,sans-serif;letter-spacing:1px}.r1-workspace .r1-install-footer{grid-column:1/-1;display:flex;align-items:center;gap:14px;flex-wrap:wrap}.r1-workspace .r1-install-footer p{flex:1;min-width:220px;margin:0;color:var(--muted);font-size:11px}.r1-workspace .r1-server-section-title{margin:20px 0 10px;font-size:14px!important;font-weight:600}.r1-workspace .server-layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:16px;margin-top:16px}.r1-workspace .table-scroll{overflow:auto}.r1-workspace .server-table{width:100%;border-collapse:collapse;text-align:left}.r1-workspace .server-table th,.r1-workspace .server-table td{padding:12px 10px;border-bottom:1px solid var(--line);font-size:11px}.r1-workspace .server-table th{color:var(--faint);font-weight:500}.r1-workspace .server-table tr.selected td{background:color-mix(in srgb,var(--accent) 6%,transparent)}.r1-workspace .server-name{display:flex;align-items:center;gap:8px}.r1-workspace .server-name button{min-width:0;text-align:left}.r1-workspace .favorite{color:var(--faint)}.r1-workspace .favorite.saved{color:var(--accent)}.r1-workspace .server-name strong,.r1-workspace .server-name small,.r1-workspace .server-map{display:block}.r1-workspace .server-name strong{font-size:11px}.r1-workspace .server-name small,.r1-workspace .server-map,.r1-workspace .faint{margin-top:4px;color:var(--muted);font-size:9px}.r1-workspace .num{text-align:right;white-space:nowrap}.r1-workspace .table-foot{display:flex;justify-content:space-between;padding-top:12px;color:var(--muted);font-size:10px}.r1-workspace .server-banner{height:75px;display:flex;align-items:end;padding:12px;background:linear-gradient(120deg,color-mix(in srgb,var(--accent) 18%,var(--surface)),var(--surface));border-bottom:1px solid var(--line);color:var(--accent);font:10px Arial,sans-serif;letter-spacing:1px}.r1-workspace .server-detail h2{margin:16px 0 8px;font-size:17px!important}.r1-workspace .detail-description{color:var(--muted);font-size:11px;line-height:1.6}.r1-workspace .detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.r1-workspace .detail-grid dt{color:var(--faint);font-size:9px}.r1-workspace .detail-grid dd{margin:4px 0 0;font-size:11px;overflow-wrap:anywhere}.r1-workspace .r1-password{display:grid;gap:6px;margin:12px 0;color:var(--muted);font-size:10px}.r1-workspace .detail-actions>*{flex:1}.r1-workspace .empty{padding:42px 12px;text-align:center;color:var(--muted)}.r1-workspace .empty strong{display:block;margin:10px 0;color:var(--text)}.r1-workspace .empty p{font-size:11px}
  @media(max-width:900px){.r1-workspace .mods-layout{grid-template-columns:175px minmax(0,1fr);gap:16px}.r1-workspace .server-layout{grid-template-columns:1fr}.r1-workspace .server-detail{grid-column:1}.r1-workspace .mod-row{grid-template-columns:22px 26px minmax(0,1fr)}.r1-workspace .mod-row>.actions{grid-column:3;justify-content:flex-end}}
  @media(max-width:620px){.r1-workspace .page-heading{align-items:flex-start;flex-direction:column}.r1-workspace .mods-layout,.r1-workspace .r1-install-grid{grid-template-columns:1fr}.r1-workspace .mods-sidebar{border-right:0;border-bottom:1px solid var(--line);padding:0 0 14px}.r1-workspace .scope-choice{grid-template-columns:repeat(3,minmax(0,1fr))}.r1-workspace .r1-context{flex-wrap:wrap}.r1-workspace .r1-install-footer{align-items:flex-start}.r1-workspace .server-table th,.r1-workspace .server-table td{padding:9px 6px}.r1-workspace .server-layout .panel{padding:14px}}
`;
document.head.append(deltaStyle);
window.createDeltaViews=function({state,call,ok,render,navigate,report,toast,updateSwitch,protectMotion,esc,I,btn,toggle,heading,refreshStatus,importFeedback}){
  let data={addons:[],gameInstalled:false,addonsPath:''},preview=null,loading=false,busy=false,error='',filter='all',query='',type='all';
  let serverData={servers:[],status:'idle'},serverQuery='',mode='all',map='all',selected=null,serverPassword='',serverTask=null,addonTask=null;
  const pending=new Map();let tail=Promise.resolve();
  const E=value=>esc(String(value??'')),T=value=>I18n.text(value),actionId=value=>encodeURIComponent(value),decode=value=>decodeURIComponent(value);
  const disabled=()=>busy||pending.size>0;
  const label=(text,action,icon='',style='')=>btn(text,action,icon,style).replace('<button','<button'+(disabled()?' disabled':''));
  const empty=(title,description)=>`<div class="empty">${I('cube')}<strong>${T(title)}</strong><p>${T(description)}</p></div>`;
  function identity(title,kicker,actions=''){return `<div class="page-heading"><div class="collection-identity"><span class="collection-kicker">TITANFALL 1 / ${kicker}</span><h1>${T(title)}</h1></div><div class="heading-actions">${actions}</div></div>`;}
  function mods(){
    const list=data.addons.filter(row=>(filter==='all'||(filter==='enabled')===row.enabled)&&(type==='all'||row.type===type)&&[row.title,row.author,row.description,row.name].join(' ').toLowerCase().includes(query.toLowerCase()));
    return `<div class="mods-editorial r1-workspace" data-collection="delta">${identity('我的模组','ADDON COLLECTION',label('打开模组目录','r1-open','folder')+label('导入模组','r1-import','upload','primary'))}<div class="r1-context"><span>R1DELTA / ADDONS</span><span>${T('泰坦陨落 1')}</span><button class="text-button" data-action="r1-directory">${T('选择游戏目录')}</button></div><div class="mods-layout"><aside class="mods-sidebar"><div class="side-section"><h3>${T('模组状态')}</h3><div class="scope-choice">${[['all','全部模组'],['enabled','已启用'],['disabled','已停用']].map(([key,title])=>`<button class="${filter===key?'active':''}" aria-pressed="${filter===key}" data-action="r1-filter-${key}">${T(title)}<span>${data.addons.filter(row=>key==='all'||(key==='enabled')===row.enabled).length}</span></button>`).join('')}</div><hr class="side-separator"><h3>${T('模组格式')}</h3><div class="scope-choice">${[['all','全部格式'],['folder','文件夹'],['vpk','VPK']].map(([key,title])=>`<button class="${type===key?'active':''}" aria-pressed="${type===key}" data-action="r1-type-${key}">${T(title)}</button>`).join('')}</div><hr class="side-separator"><button class="text-button" data-action="r1-backups">${T('打开备份目录')} ${I('arrow-up-right')}</button></div></aside><div class="collection-work"><div class="toolbar"><label class="search">${I('search')}<input id="r1-addon-search" placeholder="${T('搜索模组')}" aria-label="${T('搜索模组')}" value="${E(query)}"></label>${label('刷新列表','r1-refresh','refresh','ghost')}<span class="spacer"></span><span class="count-label">${data.addons.filter(row=>row.enabled).length} / ${data.addons.length} ${T('已启用')}</span></div><div class="path-strip"><div class="grow"><div class="path-label">${T('模组目录')}</div><p class="path">${E(data.addonsPath||T('尚未选择游戏目录'))}</p></div></div><div role="status" class="r1-feedback">${T(error||(!data.gameInstalled?'请先选择泰坦陨落 1 游戏目录':loading?'正在读取 Addon':'修改将在下次启动 Delta 时生效'))}</div><section class="mod-list" id="r1-addon-results">${list.length?list.map((row,index)=>`<article class="mod-row" data-mod="r1:${E(row.id)}" data-enabled="${row.enabled}"><span class="mod-index">${String(index+1).padStart(2,'0')}</span><div class="mod-glyph">${I(row.type==='vpk'?'file':'folder')}</div><div class="grow"><div class="mod-title"><strong>${E(row.title)}</strong><span class="badge">${row.type==='vpk'?'VPK':T('文件夹')}</span></div>${row.description?`<p>${E(row.description)}</p>`:''}<div class="mod-meta">${E([row.author,row.version,row.name].filter(Boolean).join(' / '))}</div>${row.error?`<small class="r1-warning">${T(row.error)}</small>`:''}</div><div class="actions"><span class="mod-state">${T(row.enabled?'已启用':'已停用')}</span>${toggle(row.enabled,'r1-toggle-'+actionId(row.id),T('启用')+' '+row.title,busy||!row.valid)}<button class="icon-button" data-action="r1-remove-${actionId(row.id)}" aria-label="${T('卸载模组')} ${E(row.title)}" ${disabled()?'disabled':''}>${I('trash')}</button></div></article>`).join(''):empty('这里还没有模组',data.gameInstalled?'选择 ZIP、VPK 或 Addon 文件夹导入。':'请先选择泰坦陨落 1 游戏目录')}</section></div></div></div>`;
  }
  function installer(){
    return `<div class="r1-workspace r1-installer">${identity('模组安装','ADDON WORKBENCH','<span class="r1-format-label">VPK / ADDON</span>')}<div class="r1-install-grid"><section class="panel"><div class="panel-header"><h2><span class="section-index">01</span>${T('导入模组')}</h2><span class="badge">R1DELTA</span></div><div class="dropzone" id="r1-dropzone"><div class="upload-icon">${I('upload')}</div><strong>${T('把模组拖到这里')}</strong><small>${T('ZIP、单文件 VPK 或 Addon 文件夹')}</small><div class="row">${label('选择文件','r1-choose-file','file','soft')}${label('选择文件夹','r1-choose-folder','folder','ghost')}</div></div><div class="r1-import-guide"><h3>${T('支持的安装方式')}</h3><p>${T('VPK 直接导入；ZIP 自动识别其中的 Addon。')}</p><p>${T('文件夹需包含 addoninfo.txt，保留作者提供的目录结构。')}</p><p>${T('北极星和 Icepick 模组请切换到泰坦陨落 2 安装。')}</p></div></section><section class="panel install-details" id="install-details"><div class="panel-header"><h2><span class="section-index">02</span>${T('安装预览')}</h2>${preview?label('清除','r1-clear','','ghost'):''}</div>${preview?`<p class="path">${E(preview.sourceName)}</p><div class="r1-preview-list">${preview.entries.map(row=>`<div class="r1-preview-row"><span>${row.type==='vpk'?'VPK':'ADDON'}</span><div><strong>${E(row.title)}</strong><p class="path">r1/addons/${E(row.name)}</p><small>${T(row.replaces?'将替换同名模组，原文件会保留备份。':'安装后启用')}</small></div></div>`).join('')}</div><div class="path-strip"><div class="grow"><div class="path-label">${T('安装位置')}</div><p class="path">${E(data.addonsPath||T('尚未选择游戏目录'))}</p></div>${label('选择游戏目录','r1-directory','folder','ghost')}</div>${label(busy?'正在处理…':'安装模组','r1-install','download','primary')}`:empty('尚未选择模组','选择文件后，在这里确认安装内容和目录。')}<p class="r1-feedback" role="status">${T(error)}</p></section><section class="panel r1-install-footer"><span>R1DELTA / ADDONLIST</span><p>${T('模组与 Delta 核心分开保存，更新核心时保留模组。')}</p>${label('查看已安装模组','r1-library','cube','ghost')}${label('打开备份目录','r1-backups','folder','ghost')}</section></div></div>`;
  }
  function filteredServers(){return serverData.servers.filter(row=>(mode==='all'||row.mode===mode)&&(map==='all'||row.map===map)&&[row.name,row.map,row.mode].join(' ').toLowerCase().includes(serverQuery.toLowerCase()));}
  function servers(){
    const rows=filteredServers();if(!rows.some(row=>row.key===selected)){selected=rows[0]?.key||null;serverPassword='';}const chosen=rows.find(row=>row.key===selected);
    const select=(id,title,values,value)=>`<select id="${id}" aria-label="${T(title)}"><option value="all">${T(title)}</option>${[...new Set(values)].filter(Boolean).map(item=>`<option value="${E(item)}" ${item===value?'selected':''}>${E(item)}</option>`).join('')}</select>`;
    return `<div class="r1-workspace">${identity('社区服务器','R1DELTA / LIVE',label('刷新列表','r1-servers-refresh','refresh'))}<div class="toolbar"><span class="badge">R1DELTA</span><label class="search">${I('search')}<input id="r1-server-search" aria-label="${T('搜索服务器')}" placeholder="${T('搜索服务器、地图…')}" value="${E(serverQuery)}"></label>${select('r1-server-mode','所有模式',serverData.servers.map(row=>row.mode),mode)}${select('r1-server-map','所有地图',serverData.servers.map(row=>row.map),map)}</div><h2 class="r1-server-section-title">${T('全部服务器')}</h2>${serverData.status==='loading'||serverData.status==='unavailable'||serverData.status==='stale'?`<p class="r1-feedback" role="status">${T(serverData.status==='loading'?'正在读取服务器列表':serverData.status==='unavailable'?'Delta 服务器列表暂时不可用':'连接失败，正在显示上次的服务器列表')}</p>`:''}<div class="server-layout"><section class="panel list-panel"><div class="table-scroll"><table class="server-table"><thead><tr><th>${T('服务器名称')}</th><th>${T('模式 / 地图')}</th><th class="num">${T('当前玩家')}</th></tr></thead><tbody>${rows.map(row=>`<tr class="${row.key===selected?'selected':''}"><td><div class="server-name"><button class="r1-server-select" data-action="r1-server-view-${row.key}"><strong>${E(row.name)}</strong><small>${E(row.version)}${row.password?' / '+T('需要密码'):''}</small></button></div></td><td>${E(row.mode)}<span class="server-map">${E(row.map)}</span></td><td class="num">${row.players}<span class="faint"> / ${row.maxPlayers}</span></td></tr>`).join('')}</tbody></table>${!rows.length?empty('没有匹配的服务器','试试其他关键词或刷新列表。'):''}</div><div class="table-foot"><span>${rows.length} ${T('个服务器')}</span><span>${serverData.fetchedAt?new Date(serverData.fetchedAt).toLocaleTimeString(I18n.current):'—'}</span></div></section>${chosen?`<aside class="panel server-detail"><div class="server-banner"><span>${E(chosen.map)}</span></div><h2 class="detail-title">${E(chosen.name)}</h2><p class="detail-description">${E(chosen.description)}</p><dl class="detail-grid"><div><dt>${T('游戏模式')}</dt><dd>${E(chosen.mode)}</dd></div><div><dt>${T('当前玩家')}</dt><dd>${chosen.players} / ${chosen.maxPlayers}</dd></div><div><dt>${T('客户端')}</dt><dd>R1Delta ${E(chosen.version)}</dd></div><div><dt>${T('服务器地址')}</dt><dd><code>${E(chosen.address)}</code></dd></div></dl>${chosen.password?`<label class="r1-password">${T('服务器密码')}<input id="r1-server-password" type="password" autocomplete="off" maxlength="128" value="${E(serverPassword)}"></label>`:''}<div class="detail-actions">${label('启动 Delta 并加入','r1-server-join-'+chosen.key,'play','primary')}${label('复制地址','r1-server-copy-'+chosen.key,'copy')}</div><p class="r1-feedback">${T('已在游戏中时，可在 Delta 内置服务器列表加入。')}</p></aside>`:''}</div></div>`;
  }
  async function refresh(){if(addonTask)return addonTask;loading=true;error='';addonTask=(async()=>{try{data=ok(await call('r1delta-addons-list'));for(const [id,row]of pending){const item=data.addons.find(item=>item.id===id);if(item)item.enabled=row.desired;}}catch(cause){error=cause.message;report(cause);}finally{loading=false;addonTask=null;render();}})();return addonTask;}
  async function refreshServers(force=false){if(serverTask)return serverTask;serverData={...serverData,status:'loading'};render();serverTask=(async()=>{try{serverData=ok(await call('r1delta-servers',{force}));}catch(cause){serverData={...serverData,status:'unavailable'};report(cause);}finally{serverTask=null;render();}})();return serverTask;}
  async function run(task){if(disabled())return;busy=true;error='';render();try{return await task();}catch(cause){error=cause.message;report(cause);}finally{busy=false;render();}}
  async function ensureDirectory(){await refresh();if(data.gameInstalled)return true;const value=ok(await call('r1delta-select'));if(!value)return false;await refreshStatus();await refresh();return data.gameInstalled;}
  async function inspect(input){return run(async()=>{
    if(state.page!=='installer')navigate('installer');
    const dropped=Boolean(input.path),name=dropped?String(input.name||input.path).split(/[\\/]/).pop():'';
    preview=null;
    importFeedback.set({game:'tf1',stage:dropped?'reading':'choosing',name,detail:dropped?'正在检查文件内容':'',percent:null});render();await importFeedback.frame();
    try{
      if(!await ensureDirectory()){importFeedback.set({stage:'cancelled',detail:'',percent:null});return;}
      const value=ok(await call('r1delta-addons-inspect',input));
      if(!value){importFeedback.set({stage:'cancelled',detail:'',percent:null});return;}
      preview=value;
      importFeedback.set({stage:'ready',name:value.sourceName||name,detail:'',percent:null});render();
    }catch(cause){importFeedback.set({stage:'readError',detail:cause.message||String(cause),percent:null});throw cause;}
  });}
  function toggleAddon(id){
    const item=data.addons.find(row=>row.id===id);if(!item||!item.valid||busy)return;
    let request=pending.get(id);if(request){request.desired=!request.desired;item.enabled=request.desired;updateSwitch('r1-toggle-'+actionId(id),item.enabled);protectMotion();return request.task;}
    request={desired:!item.enabled,confirmed:item.enabled};pending.set(id,request);item.enabled=request.desired;updateSwitch('r1-toggle-'+actionId(id),item.enabled);protectMotion();render();
    request.task=tail=tail.catch(()=>{}).then(async()=>{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));try{while(request.desired!==request.confirmed){const desired=request.desired;ok(await call('r1delta-addons-toggle',{id,enabled:desired}));request.confirmed=desired;}}catch(cause){error=cause.message;report(cause);}finally{item.enabled=request.confirmed;pending.delete(id);updateSwitch('r1-toggle-'+actionId(id),item.enabled);await refresh();}});return request.task;
  }
  async function dispatch(action){
    if(action.startsWith('r1-toggle-'))return toggleAddon(decode(action.slice(10)));
    if(action.startsWith('r1-filter-')){filter=action.slice(10);render();return;}
    if(action.startsWith('r1-type-')){type=action.slice(8);render();return;}
    if(action.startsWith('r1-server-view-')){const next=action.slice(15);if(next!==selected)serverPassword='';selected=next;render();return;}
    if(action.startsWith('r1-server-copy-'))return run(async()=>{ok(await call('r1delta-server-copy',action.slice(15)));toast('服务器地址已复制');});
    if(action.startsWith('r1-server-join-')){
      const key=action.slice(15),password=document.getElementById('r1-server-password')?.value||'';
      return run(async()=>{let status=ok(await call('r1delta-status'));if(!status.installed||!status.gameInstalled){status=ok(await call('r1delta-install'));if(!status)return;await refreshStatus();}ok(await call('r1delta-server-join',{key,password}));toast('已发送 Delta 加入请求');});
    }
    if(action.startsWith('r1-remove-'))return run(async()=>{const id=decode(action.slice(10)),item=data.addons.find(row=>row.id===id);if(!item||!confirm(T('卸载此 Addon？文件会移入备份目录。')+'\n'+item.title))return;data=ok(await call('r1delta-addons-remove',{id}));toast('Addon 已卸载');});
    switch(action){
      case 'r1-import':return inspect({});case 'r1-choose-file':return inspect({kind:'file'});case 'r1-choose-folder':return inspect({kind:'folder'});
      case 'r1-directory':return run(async()=>{const value=ok(await call('r1delta-select'));if(!value)return;preview=null;ok(await call('r1delta-addons-clear'));importFeedback.set({stage:'idle'});await refreshStatus();await refresh();});
      case 'r1-open':case 'r1-backups':return run(async()=>{if(await ensureDirectory())ok(await call('r1delta-addons-open',action==='r1-backups'?'backups':'addons'));});
      case 'r1-clear':return run(async()=>{ok(await call('r1delta-addons-clear'));preview=null;importFeedback.set({stage:'idle'});});
      case 'r1-refresh':return refresh();case 'r1-library':navigate('mods');return;case 'r1-servers-refresh':return refreshServers(true);
      case 'r1-install':return run(async()=>{
        if(!preview)return;const replace=preview.entries.some(row=>row.replaces);if(replace&&!confirm(T('替换同名 Addon？原文件会保留备份。')))return;
        importFeedback.set({game:'tf1',stage:'installing',name:preview.sourceName,detail:'正在准备安装',percent:null});await importFeedback.frame();
        try{const result=ok(await call('r1delta-addons-install',{token:preview.token,replace}));if(!result){importFeedback.set({stage:'ready',detail:'',percent:null});return;}data=result;preview=null;importFeedback.set({stage:'done',detail:'',percent:100});toast('Delta Addon 安装完成');}
        catch(cause){importFeedback.set({stage:'installError',detail:cause.message||String(cause),percent:null});throw cause;}
      });
    }
  }
  function onInput(event){
    if(state.title!=='tf1')return;const element=event.target,id=element.id;
    if(id==='r1-server-password'){serverPassword=element.value;return;}
    if(!['r1-addon-search','r1-server-search','r1-server-mode','r1-server-map'].includes(id))return;
    if(id==='r1-addon-search')query=element.value;else if(id==='r1-server-search')serverQuery=element.value;else if(id==='r1-server-mode')mode=element.value;else map=element.value;
    const cursor=element.selectionStart;render();requestAnimationFrame(()=>{const input=document.getElementById(id);if(input){input.focus({preventScroll:true});if(typeof cursor==='number')input.setSelectionRange(cursor,cursor);}});
  }
  document.addEventListener('input',onInput);document.addEventListener('change',event=>{if(event.target.tagName==='SELECT')onInput(event);});
  document.addEventListener('dragover',event=>{const zone=event.target.closest?.('#r1-dropzone');if(zone){event.preventDefault();zone.classList.add('dragover');}});
  document.addEventListener('dragleave',event=>event.target.closest?.('#r1-dropzone')?.classList.remove('dragover'));
  document.addEventListener('drop',event=>{if(state.title!=='tf1'||!event.target.closest?.('#r1-dropzone'))return;event.preventDefault();event.stopImmediatePropagation();event.target.closest('#r1-dropzone').classList.remove('dragover');if(event.dataTransfer.files.length!==1){toast('请一次导入一个文件或文件夹');return;}inspect({path:fold.getDroppedFilePath(event.dataTransfer.files[0]),name:event.dataTransfer.files[0].name}).catch(report);},true);
  ipcRenderer.on('r1delta-addon-progress',(_event,value)=>{
    if(importFeedback.state.game!=='tf1')return;
    if(value.stage==='reading'&&['choosing','reading'].includes(importFeedback.state.stage)){importFeedback.set({stage:'reading',name:value.sourceName||importFeedback.state.name,detail:'正在检查文件内容',percent:null});return;}
    if(importFeedback.state.stage!=='installing')return;
    const percent=Number.isFinite(value.percent)?Math.min(100,Math.max(0,value.percent)):null;
    importFeedback.set({detail:percent>=100?'正在完成安装':'正在写入文件',percent:percent===null?null:Math.min(99,percent)});
  });
  return {mods,installer,servers,dispatch,refresh,refreshServers,get busy(){return busy||pending.size>0;}};
};
